hp?page=users">Cancelar</a><?php endif;?></div></form></article>
<article class="panel-card edit-panel" id="role-form"><h2><?=$editRole?'Editar rol':'Crear rol'?></h2><form method="post" class="form-grid app-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="<?=$editRole?'role_update':'role_create'?>"><input type="hidden" name="return_page" value="users"><input type="hidden" name="role_id" value="<?=(int)($editRole['id']??0)?>"><?php if(!$editRole):?><label class="form-field"><span>Identificador</span><input name="role_name" pattern="[a-z][a-z0-9_]{2,39}" maxlength="40" placeholder="ej. assistant" required></label><?php endif;?><label class="form-field"><span>Nombre visible</span><input name="role_label" maxlength="80" value="<?=e($editRole['label']??'')?>" required></label><label class="form-field"><span>Descripción</span><input name="role_description" maxlength="255" value="<?=e($editRole['description']??'')?>"></label><?php if(!$editRole||!in_array($editRole['name'],['system_admin','admin','career_coordinator','teacher','student'],true)):?><label class="form-field"><span>Perfil de permisos</span><select name="access_profile" required><?php foreach(['admin'=>'Solo lectura','career_coordinator'=>'Coordinador de carrera','teacher'=>'Docente','student'=>'Estudiante'] as $profileKey=>$profileLabel):?><option value="<?=e($profileKey)?>" <?=($editRole['access_profile']??'admin')===$profileKey?'selected':''?>><?=e($profileLabel)?></option><?php endforeach;?></select></label><?php else:?><input type="hidden" name="access_profile" value="<?=e($editRole['access_profile'])?>"><p class="page-subtitle">El perfil de permisos de los roles base está protegido.</p><?php endif;?><div class="form-actions"><button class="button-primary" type="submit"><?=$editRole?'Guardar rol':'Crear rol'?></button><?php if($editRole):?><a class="button-secondary" href="index.php?page=users">Cancelar</a><?php endif;?></div></form></article>
<article class="panel-card catalog-panel"><div class="catalog-toolbar"><div class="catalog-title"><h2>Solicitudes de alta</h2><p><?=count($requests)?> solicitudes</p></div></div><div class="table-responsive"><table class="data-table"><thead><tr><th>PERSONA</th><th>PERFIL</th><th>CARRERA</th><th>COORDINADOR</th><th>ESTADO</th><th>ACCIONES</th></tr></thead><tbody><?php foreach($requests as $request):?><tr><td><strong><?=e($request['full_name'])?></strong><small class="table-subline"><?=e($request['email'])?><?=!empty($request['message'])?' · '.e($request['message']):''?></small></td><td><?=e($request['requested_role']==='teacher'?'Docente':'Estudiante')?></td><td><?=e($request['career_name'])?></td><td><?=e($request['coordinator_name'])?></td><td><?=e($requestStatusLabels[$request['status']]??$request['status'])?></td><td><?php if($request['status']==='pending'):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="user_request_review"><input type="hidden" name="return_page" value="users"><input type="hidden" name="request_id" value="<?=(int)$request['id']?>"><button class="button-secondary button-small" name="decision" value="approved" type="submit">Aprobar</button> <button class="button-secondary button-small" name="decision" value="rejected" type="submit">Rechazar</button></form><?php elseif($request['status']==='approved'):?><a class="row-action" href="index.php?page=users&amp;request=<?=(int)$request['id']?>#user-form">Completar alta</a><?php endif;?></td></tr><?php endforeach;?><?php if(!$requests):?><tr><td colspan="6">No hay solicitudes.</td></tr><?php endif;?></tbody></table></div></article>
<article class="panel-card catalog-panel"><div class="catalog-toolbar"><div class="catalog-title"><h2>Roles del sistema</h2><p><?=count($roles)?> roles</p></div></div><div class="table-responsive"><table class="data-table"><thead><tr><th>ROL</th><th>PERFIL</th><th>USUARIOS</th><th>ACCIONES</th></tr></thead><tbody><?php foreach($roles as $r):?><tr><td><strong><?=e($r['label'])?></strong><small class="table-subline"><?=e($r['name'])?> · <?=e($r['description'])?></small></td><td><?=e($roleLabels[$r['access_profile']]??$r['access_profile'])?></td><td><?=(int)$r['user_count']?></td><td><a class="row-action" href="index.php?page=users&amp;edit_role=<?=(int)$r['id']?>#role-form">Editar</a><?php if(!in_array($r['name'],['system_admin','admin','career_coordinator','teacher','student'],true)&&!(int)$r['user_count']):?><form method="post" data-confirm="¿Eliminar este rol?"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="role_delete"><input type="hidden" name="return_page" value="users"><input type="hidden" name="role_id" value="<?=(int)$r['id']?>"><button class="row-action danger" type="submit">Eliminar</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></article>
<?php endif;?>
<?php if(in_array($role,['system_admin','admin'],true)):?><article class="panel-card catalog-panel"><div class="catalog-toolbar"><div class="catalog-title"><h2>Directorio de usuarios</h2><p><?=count($users)?> cuentas</p></div><label class="table-search"><input type="search" placeholder="Buscar usuario" data-table-filter="users"></label></div><div class="table-responsive"><table class="data-table"><thead><tr><th>USUARIO</th><th>ROL</th><th>CARRERA</th><th>ESTADO</th><?php if($isSystemAdmin):?><th>ACCIONES</th><?php endif;?></tr></thead><tbody><?php foreach($users as $account):?><tr data-search-row="users"><td><strong><?=e($account['full_name'])?></strong><small class="table-subline"><?=e($account['email'])?></small></td><td><?=e($account['role_label'])?></td><td><?=e($account['career_name']?:'—')?></td><td><?=e($account['status'])?></td><?php if($isSystemAdmin):?><td><?php if((int)$account['id']!==(int)$user['id']):?><a class="row-action" href="index.php?page=users&amp;edit=<?=(int)$account['id']?>#user-form">Editar</a><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="user_status"><input type="hidden" name="return_page" value="users"><input type="hidden" name="user_id" value="<?=(int)$account['id']?>"><button class="button-secondary button-small" type="submit"><?=$account['status']==='active'?'Desactivar':'Activar'?></button></form><form method="post" data-confirm="¿Eliminar esta cuenta? Los datos académicos se conservarán."><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="user_delete"><input type="hidden" name="return_page" value="users"><input type="hidden" name="user_id" value="<?=(int)$account['id']?>"><button class="row-action danger" type="submit">Eliminar</button></form><?php endif;?></td><?php endif;?></tr><?php endforeach;?></tbody></table></div></article><?php endif;?>
